    public static function enqueueLocked(PDO $db,int $org,int $order,int $actor,string $key='confirmation'):array
    {
        if(!$db->inTransaction())throw new LogicException('Ticket delivery enqueue requires the settlement transaction.');$o=CommerceStore::row($db,'orders',$org,$order,true);if($o['state']!=='paid')throw new RuntimeException('Only confirmed paid/complimentary tickets can be queued.');if(!preg_match('/^[a-zA-Z0-9_-]{1,100}$/',$key))throw new RuntimeException('Invalid delivery request.');
        $q=$db->prepare('SELECT * FROM commerce_deliveries WHERE organization_id=? AND order_id=? AND delivery_key=?');$q->execute([$org,$order,$key]);if($prior=$q->fetch())return$prior;
        if($key!=='confirmation'){$q=$db->prepare('SELECT COUNT(*) FROM commerce_deliveries WHERE organization_id=? AND order_id=? AND created_at_utc>DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 HOUR)');$q->execute([$org,$order]);if((int)$q->fetchColumn()>=3)throw new RuntimeException('Ticket delivery is rate limited. Try again after an hour or use the current ticket page.');}
        $q=$db->prepare("SELECT COUNT(*) FROM commerce_tickets WHERE organization_id=? AND order_id=? AND state='valid'");$q->execute([$org,$order]);if((int)$q->fetchColumn()<1)throw new RuntimeException('No valid tickets are available for delivery.');$token=CommerceStorefrontService::issueLinkLocked($db,$org,$order,$actor);$base=(string)(getenv('COMMERCE_PUBLIC_BASE_PATH')?:getenv('APP_BASE_PATH')?:'');if($base!==''&&!preg_match('~^/[a-zA-Z0-9/_-]+$~',$base))$base='';$path=$base.'/tickets/order?'.http_build_query(['token'=>$token]);$reference=bin2hex(random_bytes(16));$body=self::body($db,$org,$o,$path);$id=MailService::queue($db,null,$o['customer_email'],$o['customer_name'],'commerce',$body['subject'],$body['text'],$body['html'],'commerce-ticket-'.$org.'-'.$order.'-'.$key);if(!$id)throw new RuntimeException('Delivery queue identity conflict.');$verify=$db->prepare('SELECT category FROM email_queue WHERE id=?');$verify->execute([$id]);if($verify->fetchColumn()!=='commerce')throw new RuntimeException('Commerce mail service version mismatch.');$db->prepare("UPDATE email_queue SET status='commerce_queued' WHERE id=?")->execute([$id]);
        $db->prepare('INSERT INTO commerce_deliveries(organization_id,order_id,email_queue_id,delivery_key,public_reference,retrieval_path,token_hash,available_at_utc,actor_user_id,created_at_utc) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP(),?,UTC_TIMESTAMP())')->execute([$org,$order,$id,$key,$reference,$path,hash('sha256',$token),$actor]);$delivery=(int)$db->lastInsertId();CommerceStore::audit($db,$org,$actor,'commerce.ticket_delivery_queued','order',$order,['delivery'=>$delivery,'queue'=>$id,'kind'=>$key==='confirmation'?'confirmation':'resend']);$q=$db->prepare('SELECT * FROM commerce_deliveries WHERE id=?');$q->execute([$delivery]);return$q->fetch();
    }
    private static function body(PDO $db,int $org,array $o,string $url):array
    {
        $q=$db->prepare('SELECT c.*,p.title,s.name auditorium,v.name venue FROM commerce_performances c JOIN productions p ON p.id=c.production_id JOIN commerce_layouts l ON l.id=c.layout_id AND l.organization_id=c.organization_id JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE c.organization_id=? AND c.id=?');$q->execute([$org,$o['performance_id']]);$p=$q->fetch();if(!$p)throw new RuntimeException('Performance unavailable.');$brand=OrganizationBranding::fromEnvironment();$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$subject=mb_substr(preg_replace('/[\r\n]+/',' ',$brand['name'].' · Your sandbox tickets'),0,250);$lines=[$brand['name'].' · Sandbox confirmation','Order '.$o['public_reference'],$p['title'],CommercePerformancePolicy::label($p),$p['venue'].' / '.$p['auditorium']];$html='<html><body style="background:#faf7f1;color:#30282a;font-family:Arial,sans-serif;padding:24px"><h1 style="color:#702a3f;font-family:Georgia,serif">'.$e($brand['name']).'</h1><p>Sandbox tickets · no real-world admission</p><h2>'.$e($p['title']).'</h2><p>'.$e(CommercePerformancePolicy::label($p)).'<br>'.$e($p['venue'].' / '.$p['auditorium']).'</p><table><caption>Your tickets</caption><tr><th>Seat / admission</th><th>Type</th></tr>';
        $q=$db->prepare("SELECT l.description,l.category FROM commerce_tickets t JOIN commerce_order_lines l ON l.organization_id=t.organization_id AND l.order_id=t.order_id AND l.seat_key=t.seat_key WHERE t.organization_id=? AND t.order_id=? AND t.state='valid' ORDER BY t.id");$q->execute([$org,$o['id']]);foreach($q->fetchAll() as $ticket){$lines[]=$ticket['description'].' · '.$ticket['category'];$html.='<tr><td>'.$e($ticket['description']).'</td><td>'.$e($ticket['category']).'</td></tr>';}$html.='</table><dl>';foreach(['subtotal'=>'Tickets','discount'=>'Discount','tax'=>'Tax','fee'=>'Order fee','total'=>'Total'] as $key=>$label){$amount=$o['currency'].' '.number_format((int)$o[$key.'_minor']/100,2);$lines[]=$label.': '.$amount;$html.='<dt>'.$label.'</dt><dd>'.$e($amount).'</dd>';}$lines[]='Secure tickets (expires in 24 hours): '.$url;$lines[]='Open the secure ticket page for one QR per ticket and printable/PDF tickets. Preview access requires an authorized tester account. Email failure does not change ticket validity.';$html.='</dl><p><a style="display:inline-block;background:#702a3f;color:white;padding:14px 20px;border-radius:8px" href="'.$e($url).'">View secure tickets & QR codes</a></p><p>This link expires in 24 hours. Preview access requires an authorized test account. Ticket validity is checked when presented at the door.</p></body></html>';return['subject'=>$subject,'text'=>implode("\n",$lines),'html'=>$html];
    }
    public static function prepare(PDO $db,array $u,int $org,int $order,string $ownership,string $basePath):array
    {
        CommerceInventoryService::own($db,$u,$org,$order,$ownership);$d=CommerceStore::tx($db,fn()=>self::enqueueLocked($db,$org,$order,(int)$u['id'],'link-'.gmdate('YmdH')));$o=CommerceStore::row($db,'orders',$org,$order);return['transport'=>'capture_only','sent'=>false,'recipient'=>$o['customer_email'],'subject'=>'Sandbox tickets · '.$o['public_reference'],'retrieval_path'=>$d['retrieval_path'],'expires_in_hours'=>24,'delivery_id'=>(int)$d['id']];
    }
    public static function resend(PDO $db,array $u,int $org,int $order,string $key,?string $ownership=null):array
    {
        if($ownership!==null)CommerceInventoryService::own($db,$u,$org,$order,$ownership);else CommerceAccess::demand($db,$u,$org,'sell');if(!preg_match('/^[a-f0-9]{32}$/',$key))throw new RuntimeException('Reload the ticket delivery form.');return CommerceStore::tx($db,fn()=>self::enqueueLocked($db,$org,$order,(int)$u['id'],'resend-'.$key));
    }
    public static function invalidateLocked(PDO $db,int $org,int $order):void
    {
        if(!$db->inTransaction())throw new LogicException('Delivery invalidation requires the refund transaction.');$db->prepare('UPDATE commerce_order_links SET revoked_at=COALESCE(revoked_at,NOW()) WHERE organization_id=? AND order_id=?')->execute([$org,$order]);$q=$db->prepare('SELECT id,email_queue_id FROM commerce_deliveries WHERE organization_id=? AND order_id=? ORDER BY id FOR UPDATE');$q->execute([$org,$order]);foreach($q->fetchAll() as $d){$db->prepare("UPDATE email_queue SET status='suppressed',last_error='order_no_longer_deliverable' WHERE id=? AND status IN ('commerce_queued','commerce_sending')")->execute([$d['email_queue_id']]);$db->prepare("UPDATE commerce_deliveries SET last_error_code='order_no_longer_deliverable',lease_token=NULL,lease_until_utc=NULL WHERE id=?")->execute([$d['id']]);}
    }
    public static function process(PDO $db,int $org,int $limit=25,?Closure $transport=null):array
    {
        if(getenv('COMMERCE_MAIL_WORKER_ENABLED')!=='1')throw new RuntimeException('Commerce mail worker is disabled.');$limit=max(1,min(100,$limit));$result=['processed'=>0,'captured'=>0,'sent'=>0,'failed'=>0,'suppressed'=>0,'superseded'=>0];
        $q=$db->prepare('SELECT id FROM commerce_deliveries WHERE organization_id=? AND lease_until_utc<UTC_TIMESTAMP() AND lease_token IS NOT NULL ORDER BY id LIMIT 100');$q->execute([$org]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id)CommerceStore::tx($db,function()use($db,$org,$id){$q=$db->prepare('SELECT * FROM commerce_deliveries WHERE organization_id=? AND id=? AND lease_until_utc<UTC_TIMESTAMP() FOR UPDATE');$q->execute([$org,$id]);$d=$q->fetch();if(!$d)return;$db->prepare("UPDATE email_queue SET status=IF(attempts>=5,'failed','commerce_queued'),last_error='interrupted_delivery' WHERE id=? AND status='commerce_sending'")->execute([$d['email_queue_id']]);$db->prepare("UPDATE commerce_deliveries SET lease_token=NULL,lease_until_utc=NULL,last_error_code='interrupted_delivery',available_at_utc=UTC_TIMESTAMP() WHERE id=?")->execute([$id]);});
        for($i=0;$i<$limit;$i++){
            $job=CommerceStore::tx($db,function()use($db,$org){$q=$db->prepare("SELECT d.* FROM commerce_deliveries d WHERE d.organization_id=? AND d.available_at_utc<=UTC_TIMESTAMP() AND EXISTS(SELECT 1 FROM email_queue q WHERE q.id=d.email_queue_id AND q.category='commerce' AND q.status='commerce_queued') ORDER BY d.id LIMIT 1 FOR UPDATE");$q->execute([$org]);$d=$q->fetch();if(!$d)return null;$q=$db->prepare("SELECT recipient_email,recipient_name,subject,text_body,html_body,attempts FROM email_queue WHERE id=? AND category='commerce' AND status='commerce_queued' FOR UPDATE");$q->execute([$d['email_queue_id']]);$message=$q->fetch();if(!$message)return null;$d=array_merge($d,$message);$lease=bin2hex(random_bytes(32));$db->prepare("UPDATE email_queue SET status='commerce_sending',attempts=attempts+1,last_attempt_at=NOW() WHERE id=?")->execute([$d['email_queue_id']]);$driver=getenv('COMMERCE_MAIL_DRIVER')?:'capture';$db->prepare('UPDATE commerce_deliveries SET lease_token=?,lease_until_utc=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 2 MINUTE),transport=? WHERE id=?')->execute([$lease,$driver==='smtp'?'smtp':'capture',$d['id']]);$d['lease_token']=$lease;$d['driver']=$driver;return$d;});if(!$job)break;++$result['processed'];
            $status='captured';$error=null;$permanent=false;$bounced=false;
            try{$o=CommerceStore::row($db,'orders',$org,(int)$job['order_id']);$p=CommerceStore::row($db,'performances',$org,(int)$o['performance_id']);$q=$db->prepare('SELECT 1 FROM commerce_order_links WHERE token_hash=? AND organization_id=? AND revoked_at IS NULL AND expires_at_utc>UTC_TIMESTAMP()');$q->execute([$job['token_hash'],$org]);$q2=$db->prepare("SELECT COUNT(*) FROM commerce_tickets WHERE organization_id=? AND order_id=? AND state='valid'");$q2->execute([$org,$o['id']]);if($o['state']!=='paid'||$p['schedule_status']!=='scheduled'||$o['customer_email']!==$job['recipient_email']||!$q->fetchColumn()||(int)$q2->fetchColumn()<1){$status='suppressed';$error='order_or_link_unavailable';}
                elseif($job['driver']==='smtp'){$approved=array_filter(array_map('strtolower',array_map('trim',explode(',',(string)getenv('COMMERCE_MAIL_TEST_RECIPIENTS')))));if(getenv('COMMERCE_MAIL_ENABLED')!=='1'||getenv('COMMERCE_MAIL_APPROVED')!=='1'||!in_array(strtolower($job['recipient_email']),$approved,true)){ $status='suppressed';$error='smtp_or_recipient_not_approved';}else{require_once __DIR__.'/CommerceStripeService.php';$origin=CommerceStripeService::origin();$body=self::body($db,$org,$o,$origin.$job['retrieval_path']);$message=array_replace($job,['subject'=>$body['subject'],'text_body'=>$body['text'],'html_body'=>$body['html'],'commerce_reference'=>$job['public_reference']]);if($transport)$transport($message);else MailService::deliverCommerce($message);$status='sent';}}
                elseif($job['driver']!=='capture')throw new RuntimeException('Invalid Commerce mail driver.');
            }catch(Throwable $e){$status='commerce_queued';$error='transport_unavailable';$code=(int)$e->getCode();$bounced=$code>=500&&$code<600;$permanent=$bounced||(int)$job['attempts']+1>=5;if($permanent)$status='failed';}
            $finished=CommerceStore::tx($db,function()use($db,$org,$job,$status,$error,$bounced){$q=$db->prepare('SELECT lease_token FROM commerce_deliveries WHERE organization_id=? AND id=? FOR UPDATE');$q->execute([$org,$job['id']]);$lease=$q->fetchColumn();if(!is_string($lease)||!hash_equals($lease,$job['lease_token']))return false;$db->prepare('UPDATE email_queue SET status=?,sent_at=IF(?=\'sent\',NOW(),sent_at),last_error=? WHERE id=?')->execute([$status,$status,$error,$job['email_queue_id']]);$db->prepare("UPDATE commerce_deliveries SET lease_token=NULL,lease_until_utc=NULL,last_error_code=?,captured_at_utc=IF(?='captured',UTC_TIMESTAMP(),captured_at_utc),bounced_at_utc=IF(?,UTC_TIMESTAMP(),bounced_at_utc),available_at_utc=DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? SECOND) WHERE id=?")->execute([$error,$status,$bounced?1:0,min(3600,60*(2**min(6,(int)$job['attempts']))),$job['id']]);$outcome=in_array($status,['captured','sent','suppressed'],true)?$status:'failed';$db->prepare('INSERT INTO email_delivery_log(email_queue_id,transport,outcome,detail) VALUES(?,?,?,?)')->execute([$job['email_queue_id'],$job['driver'],$outcome,$error]);CommerceStore::audit($db,$org,(int)$job['actor_user_id'],'commerce.delivery_'.$outcome,'order',(int)$job['order_id'],['delivery'=>(int)$job['id'],'error_code'=>$error]);return true;});if(!$finished){++$result['superseded'];continue;}if(isset($result[$status]))++$result[$status];elseif($status==='commerce_queued')++$result['failed'];
        }return$result;
    }
    public static function receiveEvent(PDO $db,int $org,string $raw,string $signature):void
    {
        $secret=(string)getenv('COMMERCE_MAIL_WEBHOOK_SECRET');if(strlen($secret)<32||strlen($raw)>65536||!preg_match('/^t=(\d{10}),v1=([a-f0-9]{64})$/',$signature,$m)||abs(time()-(int)$m[1])>300||!hash_equals(hash_hmac('sha256',$m[1].'.'.$raw,$secret),$m[2]))throw new RuntimeException('Invalid mail event signature.');$e=json_decode($raw,true,16,JSON_THROW_ON_ERROR);if(!preg_match('/^[a-zA-Z0-9_-]{1,100}$/',(string)($e['id']??''))||!preg_match('/^[a-f0-9]{32}$/',(string)($e['delivery']??''))||!in_array($e['type']??'',['delivered','bounced','complained'],true))throw new RuntimeException('Invalid mail event.');
        CommerceStore::tx($db,function()use($db,$org,$raw,$e){$q=$db->prepare('SELECT * FROM commerce_deliveries WHERE organization_id=? AND public_reference=? FOR UPDATE');$q->execute([$org,$e['delivery']]);$d=$q->fetch();if(!$d||$d['transport']!=='smtp')throw new RuntimeException('Delivery unavailable.');$hash=hash('sha256',$raw);$q=$db->prepare('SELECT payload_hash FROM commerce_delivery_events WHERE organization_id=? AND event_id=?');$q->execute([$org,$e['id']]);if($prior=$q->fetchColumn()){if(!hash_equals($prior,$hash))throw new RuntimeException('Mail event conflict.');return;}$db->prepare('INSERT INTO commerce_delivery_events(organization_id,event_id,delivery_id,event_type,payload_hash,received_at_utc) VALUES(?,?,?,?,?,UTC_TIMESTAMP())')->execute([$org,$e['id'],$d['id'],$e['type'],$hash]);if($e['type']==='delivered'&&($d['bounced_at_utc']||$d['last_error_code']==='order_no_longer_deliverable')){CommerceStore::audit($db,$org,(int)$d['actor_user_id'],'commerce.delivery_event_ignored','order',(int)$d['order_id'],['delivery'=>$d['id']]);return;}$failed=$e['type']!=='delivered';$db->prepare('UPDATE email_queue SET status=?,last_error=? WHERE id=?')->execute([$failed?'failed':'sent',$failed?'provider_bounce_or_complaint':null,$d['email_queue_id']]);$db->prepare('UPDATE commerce_deliveries SET bounced_at_utc=IF(?,UTC_TIMESTAMP(),bounced_at_utc),last_error_code=?,lease_token=NULL,lease_until_utc=NULL WHERE id=?')->execute([$failed?1:0,$failed?'provider_bounce_or_complaint':null,$d['id']]);CommerceStore::audit($db,$org,(int)$d['actor_user_id'],'commerce.delivery_'.$e['type'],'order',(int)$d['order_id'],['delivery'=>$d['id']]);});
    }
    public static function status(PDO $db,int $org,int $order):array
    {$q=$db->prepare('SELECT d.id,d.public_reference,d.created_at_utc,d.last_error_code,d.transport,q.status,q.attempts FROM commerce_deliveries d JOIN email_queue q ON q.id=d.email_queue_id WHERE d.organization_id=? AND d.order_id=? ORDER BY d.id DESC LIMIT 10');$q->execute([$org,$order]);return$q->fetchAll();}
}
